// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialMinSum, uint256 newMinSum) public {
        vm.assume(initialMinSum != newMinSum);
        // Initialize the contract
        c.SetMinSum(initialMinSum);
        c.Initialized();
        // Try to change MinSum after initialization (should revert in reference, succeed in buggy)
        uint256 minSumBefore = c.MinSum();
        (bool success, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMinSum));
        uint256 minSumAfter = c.MinSum();
        assertTrue(!success || minSumAfter == minSumBefore);
    }
}

